Here is a code snippet written in C# that demonstrates how to retrieve activity data from the database using an API:
```csharp
using System;
using System.Collections.Generic;
using System.Linq;
using System.Net.Http;
using System.Threading.Tasks;
using Newtonsoft.Json;
namespace MyApp
{
    public class Activity
    {
        public int Id { get; set; }
        public string Name { get; set; }
        public string Category { get; set; }
        public int Priority { get; set; }
    }
    public static class ActivityApi
    {
        private static readonly HttpClient client = new HttpClient();
        private static readonly string baseUrl = "http://localhost:5000/api/activities";
        public static async Task<List<Activity>> GetActivitiesAsync()
        {
            var response = await client.GetAsync(baseUrl);
            response.EnsureSuccessStatusCode();
            var responseBody = await response.Content.ReadAsStringAsync();
            return JsonConvert.DeserializeObject<List<Activity>>(responseBody);
        }
        public static async Task<Activity> GetActivityAsync(int id)
        {
            var response = await client.GetAsync($"{baseUrl}/{id}");
            response.EnsureSuccessStatusCode();
            var responseBody = await response.Content.ReadAsStringAsync();
            return JsonConvert.DeserializeObject<Activity>(responseBody);
        }
    }
    public class Program
    {
        public static async Task Main(string[] args)
        {
            var activities = await ActivityApi.GetActivitiesAsync();
            foreach (var activity in activities)
            {
                Console.WriteLine($"{activity.Name} ({activity.Category}): {activity.Priority}");
            }
        }
    }
}
```
