#include <iostream>
#include <fstream>
#include <sstream>
#include <vector>
#include <map>
using namespace std;
int main() {
    // Open CSV file
    ifstream file("restaurant_data.csv");
    // Define variables
    string line;
    vector<string> cuisine_types;
    map<string, vector<double>> ratings_by_cuisine;
    // Read CSV file line by line
    while (getline(file, line)) {
        // Split line into columns
        stringstream ss(line);
        string column;
        int column_number = 0;
        string cuisine_type;
        double atmosphere_rating;
        double service_rating;
        while (getline(ss, column, ',')) {
            // Check column number and store data
            if (column_number == 1) {
                cuisine_type = column;
                if (ratings_by_cuisine.find(cuisine_type) == ratings_by_cuisine.end()) {
                    ratings_by_cuisine[cuisine_type] = vector<double>();
                }
                cuisine_types.push_back(cuisine_type);
            } else if (column_number == 2) {
                atmosphere_rating = stod(column);
            } else if (column_number == 3) {
                service_rating = stod(column);
            }
            column_number++;
        }
        // Store ratings by cuisine type
        ratings_by_cuisine[cuisine_type].push_back(atmosphere_rating);
        ratings_by_cuisine[cuisine_type].push_back(service_rating);
    }
    // Calculate average ratings by cuisine type
    map<string, pair<double, double>> average_ratings_by_cuisine;
    for (auto cuisine_type : cuisine_types) {
        vector<double> ratings = ratings_by_cuisine[cuisine_type];
        double atmosphere_average = accumulate(ratings.begin(), ratings.begin() + ratings.size() / 2, 0.0) / (ratings.size() / 2);
        double service_average = accumulate(ratings.begin() + ratings.size() / 2, ratings.end(), 0.0) / (ratings.size() / 2);
        average_ratings_by_cuisine[cuisine_type] = make_pair(atmosphere_average, service_average);
    }
    // Output results
    for (auto cuisine_rating : average_ratings_by_cuisine) {
        cout << "Cuisine type: " << cuisine_rating.first << endl;
        cout << "Average atmosphere rating: " << cuisine_rating.second.first << endl;
        cout << "Average service rating: " << cuisine_rating.second.second << endl;
    }
    return 0;
}
This code stores the cuisine type in a vector and creates a map that stores the ratings for each cuisine type. It then calculates the average rating for each cuisine type and stores it in a map that maps cuisine type to a pair of average ratings. Finally, it outputs the results for each cuisine type. Note that this code assumes that the cuisine type is in column 2 of the CSV file. You can adjust the code to fit your specific dataset.

