```python
def is_prime(num):
    if num <= 1:
        return False
    for i in range(2, int(num**0.5)+1):
        if num % i == 0:
            return False
    return True
def twin_primes(n):
    primes = []
    twin_primes = []
    for i in range(2, n+1):
        if is_prime(i):
            primes.append(i)
            if len(primes) > 1 and primes[-1] - primes[-2] == 2:
                twin_primes.append((primes[-2], primes[-1]))
    return twin_primes
n = int(input("Enter a number: "))
