    std::vector<std::string> hotel_names;
    std::vector<std::string> hotel_urls;
    std::vector<double> hotel_rates;
    std::vector<std::string> recommended_hotels;
    // Retrieve the HTML content for the first 5 pages of hotels in the location
    for (int page = 0; page < 5; page++)
    {
        std::string url = TRIPADVISOR_URL;
        url.replace(url.find("%s"), 2, location_code);
        url.replace(url.find("%d"), 2, std::to_string(page * 30));
        std::string content = get_html_content(url);
        parse_html_content(content, hotel_names, hotel_urls, hotel_rates);
    }
    // Filter the hotels based on the given criteria and generate the list of recommended hotels
    filter_hotels(hotel_names, hotel_urls, hotel_rates, recommended_hotels);
    // Output the list of recommended hotels
    for (const std::string& hotel : recommended_hotels)
    {
        std::cout << hotel << std::endl;
    }
    return 0;
}
