```java
import javafx.application.Application;
import javafx.scene.Group;
import javafx.scene.PerspectiveCamera;
import javafx.scene.Scene;
import javafx.scene.paint.Color;
import javafx.scene.paint.PhongMaterial;
import javafx.scene.shape.Cylinder;
import javafx.scene.transform.Rotate;
import javafx.stage.Stage;
public class DoubleHelix extends Application {
    private static final int NUM_CYLINDERS = 50;
    private static final double RADIUS = 10.0;
    private static final double PITCH = 5.0;
    private static final double HEIGHT = 100.0;
    private static final double GLOW_INTENSITY = 0.5;
    @Override
    public void start(Stage primaryStage) {
        Group root = new Group();
        // create two sets of cylinders that will be intertwined
        Group cylinders1 = createCylinders(Color.RED);
        Group cylinders2 = createCylinders(Color.BLUE);
        // rotate one set of cylinders to achieve the double helix structure
        cylinders2.getTransforms().add(new Rotate(180, Rotate.X_AXIS));
        // add the two sets of cylinders to the root group
        root.getChildren().addAll(cylinders1, cylinders2);
        // create a scene with a black background
        Scene scene = new Scene(root, 800, 600, Color.BLACK);
        // add a camera to the scene
        PerspectiveCamera camera = new PerspectiveCamera(true);
        camera.setNearClip(0.1);
        camera.setFarClip(10000.0);
        camera.setTranslateZ(-500);
        scene.setCamera(camera);
        // add a glow effect to the cylinders
        PhongMaterial material = new PhongMaterial();
        material.setDiffuseColor(Color.WHITE);
        material.setSpecularColor(Color.WHITE);
        material.setSelfIlluminationMap(new GlowMap(GLOW_INTENSITY));
        cylinders1.getChildren().forEach(cylinder -> cylinder.setMaterial(material));
        cylinders2.getChildren().forEach(cylinder -> cylinder.setMaterial(material));
        primaryStage.setScene(scene);
        primaryStage.show();
    }
    private Group createCylinders(Color color) {
        Group group = new Group();
        for (int i = 0; i < NUM_CYLINDERS; i++) {
            Cylinder cylinder = new Cylinder(RADIUS, HEIGHT);
            cylinder.setTranslateY(i * PITCH);
            cylinder.setMaterial(new PhongMaterial(color));
            group.getChildren().add(cylinder);
        }
        return group;
    }
    public static void main(String[] args) {
        launch(args);
    }
}
```
