exec($command);
// Read the file into an array
$file = file_get_contents('local_directory/filename');
$data = explode("\n", $file);
// Remove any empty elements from the array
$data = array_filter($data);
// Calculate the standard deviation
$mean = array_sum($data) / count($data);
$variance = 0.0;
