Here's the function for finding all anagrams of a given string with frequency consideration, alphabetical order, and unique count:
```
def find_anagrams(input_string):
    freq_dict = {}
    for char in input_string:
        if char in freq_dict:
            freq_dict[char] += 1
        else:
            freq_dict[char] = 1
    def recursive_anagram(prefix, freq_dict):
        if len(prefix) == len(input_string):
            return [prefix]
        result = []
        for char in freq_dict:
            if freq_dict[char] > 0:
                freq_dict_copy = freq_dict.copy()
                freq_dict_copy[char] -= 1
                result += recursive_anagram(prefix + char, freq_dict_copy)
        return result
    all_anagrams = recursive_anagram("", freq_dict)
    unique_anagrams = list(set(all_anagrams))
    unique_anagrams.sort()
    return unique_anagrams, len(unique_anagrams)
```
